import{_ as a,a as t,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · 全册易错点 · 第1–22课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第四册：流利英语 · 全册易错点 · 第1–22课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-4/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册易错点","link":"/life/english/new-concept/book-4/mistakes"},"next":{"text":"第四册：流利英语 · 全册易错点 · 第23–45课","link":"/life/english/new-concept/book-4/mistakes-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册易错点","link":"/life/english/new-concept/book-4/mistakes"},"next":{"text":"第四册：流利英语 · 全册易错点 · 第23–45课","link":"/life/english/new-concept/book-4/mistakes-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-4/mistakes-part-01.md","filePath":"life/english/new-concept/book-4/mistakes-part-01.md"}'),n={name:"life/english/new-concept/book-4/mistakes-part-01.md"};function l(i,e,r,h,p,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-全册易错点-·-第1–22课" tabindex="-1">第四册：流利英语 · 全册易错点 · 第1–22课 <a class="header-anchor" href="#第四册-流利英语-·-全册易错点-·-第1–22课" aria-label="Permalink to &quot;第四册：流利英语 · 全册易错点 · 第1–22课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="第四册-流利英语-·-全册易错点" tabindex="-1">第四册：流利英语 · 全册易错点 <a class="header-anchor" href="#第四册-流利英语-·-全册易错点" aria-label="Permalink to &quot;第四册：流利英语 · 全册易错点 {#第四册-流利英语-·-全册易错点}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="l1-·-推测情态动词与过去事件" tabindex="-1">L1 · 推测情态动词与过去事件 <a class="header-anchor" href="#l1-·-推测情态动词与过去事件" aria-label="Permalink to &quot;L1 · 推测情态动词与过去事件 {#l1-·-推测情态动词与过去事件}&quot;">​</a></h2><p>不要把 might have been made 译成“必定是造成的”；might 保留了其他解释。</p><p><strong>对照例句：</strong> The marks might have been made by tools, but their origin remains uncertain.</p><p>might have been made 是情态动词加完成时被动结构；but 连接推测与限制；their 指 marks。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-001">回看讲解和练习</a></p><h2 id="l2-·-数量词与可数性" tabindex="-1">L2 · 数量词与可数性 <a class="header-anchor" href="#l2-·-数量词与可数性" aria-label="Permalink to &quot;L2 · 数量词与可数性 {#l2-·-数量词与可数性}&quot;">​</a></h2><p>The number of insects were lower 错在主谓一致；但 A number of insects were found 中复数正确。</p><p><strong>对照例句：</strong> The number of insects was lower in the sheltered garden.</p><p>主语中心词是 number，因此用 was；of insects 限定数量的对象，lower 是表语。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-002">回看讲解和练习</a></p><h2 id="l3-·-used-to、would-与过去状态" tabindex="-1">L3 · used to、would 与过去状态 <a class="header-anchor" href="#l3-·-used-to、would-与过去状态" aria-label="Permalink to &quot;L3 · used to、would 与过去状态 {#l3-·-used-to、would-与过去状态}&quot;">​</a></h2><p>不要用 would be quiet 无背景地替代 used to be quiet；would 还可能被理解为条件结果。</p><p><strong>对照例句：</strong> The village used to be quiet, but each summer guides would welcome new climbers.</p><p>used to be 表过去状态；each summer 为 would welcome 建立反复行为的时间框架。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-003">回看讲解和练习</a></p><h2 id="l4-·-报告动词与认知距离" tabindex="-1">L4 · 报告动词与认知距离 <a class="header-anchor" href="#l4-·-报告动词与认知距离" aria-label="Permalink to &quot;L4 · 报告动词与认知距离 {#l4-·-报告动词与认知距离}&quot;">​</a></h2><p>“was reported to identify”不是“被证实能够辨认”；reported 与 proved 的证据含义不同。</p><p><strong>对照例句：</strong> The participant was reported to have identified the colour, but the test did not rule out visual cues.</p><p>was reported to 标示二手报告；to have identified 表辨认早于报告；but 引出方法限制。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-004">回看讲解和练习</a></p><h2 id="l5-·-让步从句与主句重心" tabindex="-1">L5 · 让步从句与主句重心 <a class="header-anchor" href="#l5-·-让步从句与主句重心" aria-label="Permalink to &quot;L5 · 让步从句与主句重心 {#l5-·-让步从句与主句重心}&quot;">​</a></h2><p>Although she was young, but she led the discussion. 应去掉 but；despite her youth 则不需要主谓结构。</p><p><strong>对照例句：</strong> Although Lena had little experience, the team took her proposal seriously.</p><p>although 从句提供让步背景；主句 took 为一般过去时，her proposal 是宾语。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-005">回看讲解和练习</a></p><h2 id="l6-·-not-so-much-a-as-b-的纠正性对比" tabindex="-1">L6 · not so much A as B 的纠正性对比 <a class="header-anchor" href="#l6-·-not-so-much-a-as-b-的纠正性对比" aria-label="Permalink to &quot;L6 · not so much A as B 的纠正性对比 {#l6-·-not-so-much-a-as-b-的纠正性对比}&quot;">​</a></h2><p>不要将 not so much A as B 理解成“不如 A 那么 B”；它在两个解释之间强调后者。</p><p><strong>对照例句：</strong> The argument was not so much about the score as about respect.</p><p>about the score 与 about respect 平行；not so much…as… 将解释重点移向 respect。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-006">回看讲解和练习</a></p><h2 id="l7-·-关系从句中的指代与功能说明" tabindex="-1">L7 · 关系从句中的指代与功能说明 <a class="header-anchor" href="#l7-·-关系从句中的指代与功能说明" aria-label="Permalink to &quot;L7 · 关系从句中的指代与功能说明 {#l7-·-关系从句中的指代与功能说明}&quot;">​</a></h2><p>不能把 the echo that returns 写成 the echo returns 后仍接在原宾语位置；省略主语关系词会破坏结构。</p><p><strong>对照例句：</strong> The device measures the delay between a signal and the echo that returns from the wall.</p><p>that returns from the wall 修饰 echo，that 在从句作主语，不能省略。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-007">回看讲解和练习</a></p><h2 id="l8-·-情态动词的被动结构" tabindex="-1">L8 · 情态动词的被动结构 <a class="header-anchor" href="#l8-·-情态动词的被动结构" aria-label="Permalink to &quot;L8 · 情态动词的被动结构 {#l8-·-情态动词的被动结构}&quot;">​</a></h2><p>every sample must checked 缺少 be；必须写 must be checked。</p><p><strong>对照例句：</strong> Under our workshop rules, every sample must be checked before it is packed.</p><p>must be checked 是情态被动；before 引导时间从句；under…限定规则的适用范围。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-008">回看讲解和练习</a></p><h2 id="l9-·-过去完成时与过去叙事参照点" tabindex="-1">L9 · 过去完成时与过去叙事参照点 <a class="header-anchor" href="#l9-·-过去完成时与过去叙事参照点" aria-label="Permalink to &quot;L9 · 过去完成时与过去叙事参照点 {#l9-·-过去完成时与过去叙事参照点}&quot;">​</a></h2><p>不能仅因故事发生在古代就整篇用 had done；先确定两个过去动作的关系。</p><p><strong>对照例句：</strong> By the time the messenger arrived, the clerk had hidden the letter.</p><p>arrived 是过去参照点；had hidden 表示藏信发生在到达之前；by the time 引出截止时间。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-009">回看讲解和练习</a></p><h2 id="l10-·-比较结构与范围限定" tabindex="-1">L10 · 比较结构与范围限定 <a class="header-anchor" href="#l10-·-比较结构与范围限定" aria-label="Permalink to &quot;L10 · 比较结构与范围限定 {#l10-·-比较结构与范围限定}&quot;">​</a></h2><p>rents are lower than the city centre 把租金与地点比较，应补 those in。</p><p><strong>对照例句：</strong> Office rents in the new district are lower than those in the city centre.</p><p>those 代替复数 office rents，保持比较对象一致；lower 是比较级表语。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-010">回看讲解和练习</a></p><h2 id="l11-·-动名词短语作主语" tabindex="-1">L11 · 动名词短语作主语 <a class="header-anchor" href="#l11-·-动名词短语作主语" aria-label="Permalink to &quot;L11 · 动名词短语作主语 {#l11-·-动名词短语作主语}&quot;">​</a></h2><p>Learning new skills are rewarding 中 are 应改 is；skills 只是动名词的宾语。</p><p><strong>对照例句：</strong> Learning the names of local plants gives Mei a reason to walk outdoors.</p><p>Learning…plants 是完整动名词主语，中心是活动，因此谓语用 gives，而不是受 names 影响用 give。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-011">回看讲解和练习</a></p><h2 id="l12-·-unless-与条件从句" tabindex="-1">L12 · unless 与条件从句 <a class="header-anchor" href="#l12-·-unless-与条件从句" aria-label="Permalink to &quot;L12 · unless 与条件从句 {#l12-·-unless-与条件从句}&quot;">​</a></h2><p>unless the customer will sign 不用于这里的普通未来条件；应写 signs。</p><p><strong>对照例句：</strong> In this exercise, the request will remain pending unless the customer signs the form.</p><p>unless 引出例外条件；signs 用现在时表未来条件；主句 will remain 表结果。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-012">回看讲解和练习</a></p><h2 id="l13-·-目的不定式与-so-that" tabindex="-1">L13 · 目的不定式与 so that <a class="header-anchor" href="#l13-·-目的不定式与-so-that" aria-label="Permalink to &quot;L13 · 目的不定式与 so that {#l13-·-目的不定式与-so-that}&quot;">​</a></h2><p>不要把 to collect 与 because collected 混淆：前者说明目的，后者说明已经发生的原因。</p><p><strong>对照例句：</strong> The team collected rock samples so that specialists could compare the layers.</p><p>so that 从句有独立主语 specialists，与主句 team 不同；could compare 表当时的目的。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-013">回看讲解和练习</a></p><h2 id="l14-·-第二条件句与假设距离" tabindex="-1">L14 · 第二条件句与假设距离 <a class="header-anchor" href="#l14-·-第二条件句与假设距离" aria-label="Permalink to &quot;L14 · 第二条件句与假设距离 {#l14-·-第二条件句与假设距离}&quot;">​</a></h2><p>不要看到 changed 就一律解释成过去已发生；在本条件句里它表示假设距离。</p><p><strong>对照例句：</strong> If we changed the starting value slightly, the two simulations might diverge over time.</p><p>changed 在条件句表假设；might diverge 保留结果不确定性；over time 表渐进过程。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-014">回看讲解和练习</a></p><h2 id="l15-·-whether-引导名词性从句" tabindex="-1">L15 · whether 引导名词性从句 <a class="header-anchor" href="#l15-·-whether-引导名词性从句" aria-label="Permalink to &quot;L15 · whether 引导名词性从句 {#l15-·-whether-引导名词性从句}&quot;">​</a></h2><p>whether can the data be shared 是错误疑问语序；嵌入从句用 whether the data can be shared。</p><p><strong>对照例句：</strong> The team must decide whether the preliminary data can be shared with partners.</p><p>whether 从句作 decide 的宾语；the preliminary data 在 can 前，保持陈述语序。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-015">回看讲解和练习</a></p><h2 id="l16-·-so-that-与-such-that-的结果表达" tabindex="-1">L16 · so…that 与 such…that 的结果表达 <a class="header-anchor" href="#l16-·-so-that-与-such-that-的结果表达" aria-label="Permalink to &quot;L16 · so…that 与 such…that 的结果表达 {#l16-·-so-that-与-such-that-的结果表达}&quot;">​</a></h2><p>such far away 结构错误；没有名词短语时应使用 so far away。</p><p><strong>对照例句：</strong> The crossing was so far away that several residents asked for a nearer one.</p><p>so 修饰形容词短语 far away；that 从句给出结果；one 指 crossing。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-016">回看讲解和练习</a></p><h2 id="l17-·-cause、lead-to-与-be-associated-with" tabindex="-1">L17 · cause、lead to 与 be associated with <a class="header-anchor" href="#l17-·-cause、lead-to-与-be-associated-with" aria-label="Permalink to &quot;L17 · cause、lead to 与 be associated with {#l17-·-cause、lead-to-与-be-associated-with}&quot;">​</a></h2><p>不要把 associated with 在摘要中升级为 caused；这改变了证据含义。</p><p><strong>对照例句：</strong> In the fictional survey, a wetter spring was associated with fewer rabbits near the field.</p><p>was associated with 只说明关联；In the fictional survey 限定为练习数据，未确认兔子减少的原因。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-017">回看讲解和练习</a></p><h2 id="l18-·-感官动词的主动与被动转换" tabindex="-1">L18 · 感官动词的主动与被动转换 <a class="header-anchor" href="#l18-·-感官动词的主动与被动转换" aria-label="Permalink to &quot;L18 · 感官动词的主动与被动转换 {#l18-·-感官动词的主动与被动转换}&quot;">​</a></h2><p>The animal was seen surface 缺少 to；主动 We saw it surface 才使用不带 to 结构。</p><p><strong>对照例句：</strong> The animal was seen to surface beside the boat twice.</p><p>was seen to surface 是感官动词被动结构；twice 表完整动作出现两次，没有说明动作意图。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-018">回看讲解和练习</a></p><h2 id="l19-·-同位语从句与定语从句" tabindex="-1">L19 · 同位语从句与定语从句 <a class="header-anchor" href="#l19-·-同位语从句与定语从句" aria-label="Permalink to &quot;L19 · 同位语从句与定语从句 {#l19-·-同位语从句与定语从句}&quot;">​</a></h2><p>不要把 belief 自动译成“事实”；the belief that 只标明某人持有的看法。</p><p><strong>对照例句：</strong> The belief that every dream has one fixed meaning is difficult to justify.</p><p>that…meaning 说明 belief 的内容，内部主语 every dream、谓语 has、宾语 meaning 完整。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-019">回看讲解和练习</a></p><h2 id="l20-·-过去分词作后置定语" tabindex="-1">L20 · 过去分词作后置定语 <a class="header-anchor" href="#l20-·-过去分词作后置定语" aria-label="Permalink to &quot;L20 · 过去分词作后置定语 {#l20-·-过去分词作后置定语}&quot;">​</a></h2><p>不要把 collected 当成全句唯一谓语而漏掉 were analysed；该短语只限定样本。</p><p><strong>对照例句：</strong> The samples collected on Tuesday were analysed separately.</p><p>collected on Tuesday 后置修饰 samples，相当于 that were collected；were analysed 是全句谓语。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">回看讲解和练习</a></p><h2 id="l21-·-it-is-was-that-强调句" tabindex="-1">L21 · It is/was…that 强调句 <a class="header-anchor" href="#l21-·-it-is-was-that-强调句" aria-label="Permalink to &quot;L21 · It is/was…that 强调句 {#l21-·-it-is-was-that-强调句}&quot;">​</a></h2><p>It was in 1910 when… 若意在强调时间，应使用 that；when 另可引导关系或时间从句。</p><p><strong>对照例句：</strong> It was the actor’s silence that made the final scene so tense.</p><p>the actor’s silence 是被强调主语；还原为 The actor’s silence made the final scene so tense。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">回看讲解和练习</a></p><h2 id="l22-·-what-从句作主语与表语" tabindex="-1">L22 · what 从句作主语与表语 <a class="header-anchor" href="#l22-·-what-从句作主语与表语" aria-label="Permalink to &quot;L22 · what 从句作主语与表语 {#l22-·-what-从句作主语与表语}&quot;">​</a></h2><p>That matters is… 不能替代 What matters is…；what 在从句中还承担 matters 的主语。</p><p><strong>对照例句：</strong> What matters is whether the new tool solves a real problem.</p><p>What matters 为主语从句；whether…problem 为表语从句，说明评判内容。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">回看讲解和练习</a></p>',115)])])}const f=a(n,[["render",l]]);export{u as __pageData,f as default};
